// Eingabe und Speicher
const name = "Mia";
let punkte = 7;
const schwierigkeitsgrad = "mittel";

// Verarbeitung durch eine kleine, benannte Funktion
function istBestanden(wert) {
  return wert >= 10;
}

punkte = punkte + 5;

// Entscheidung über einen Zahlenbereich
if (istBestanden(punkte)) {
  console.log(`${name} hat bestanden.`);
} else {
  console.log(`${name} übt weiter.`);
}

// Entscheidung über feste benannte Werte
switch (schwierigkeitsgrad) {
  case "leicht":
    console.log("Leichte Aufgabe");
    break;
  case "mittel":
    console.log("Mittlere Aufgabe");
    break;
  default:
    console.log("Schwierigkeitsgrad unbekannt");
}

const ergebnisse = [4, 10, 12, 7];
let summe = 0;
let bestanden = 0;

for (const ergebnis of ergebnisse) {
  summe += ergebnis;
  if (istBestanden(ergebnis)) bestanden += 1;
}

// Ausgabe
console.log({ summe, durchschnitt: summe / ergebnisse.length, bestanden });
